  "inlineSchema": "// prisma/schema.prisma\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"./node_modules/@prisma/client\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel User {\n  id               String           @id @default(cuid())\n  name             String?\n  email            String           @unique\n  password         String\n  role             Role             @default(USER)\n  stripeCustomerId String?\n  createdAt        DateTime         @default(now())\n  updatedAt        DateTime         @updatedAt\n  quotes           Quote[]\n  rentals          Rental[]\n  sessions         Session[]\n  tradeInRequests  TradeInRequest[]\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n\nmodel BuyCar {\n  id    String  @id @default(cuid())\n  make  String\n  model String\n  trim  String?\n  year  Int\n  price Float // This will be the Dealer Price from Supercar Pricing Aggregator\n\n  // Enhanced specifications from Supercar Pricing Aggregator\n  specifications    Json // Enhanced with SPA performance data\n  features          Json // Interior, exterior, safety features\n  standardEquipment Json? // Standard equipment list\n  addedOptions      Json? // Popular configurations from SPA (without prices)\n\n  // Supercar Pricing Aggregator specific fields\n  supercarData    Json? // Full SPA comprehensive data\n  baseMSRP        Float? // Base MSRP from SPA\n  performanceData Json? // Engine, horsepower, torque, 0-60, top speed, etc.\n  pricingData     Json? // Market data, trends, etc.\n\n  description String        @db.Text\n  isAvailable Boolean       @default(true)\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n  images      BuyCarImage[]\n  quotes      Quote[]\n}\n\nmodel BuyCarImage {\n  id        String  @id @default(cuid())\n  url       String\n  carId     String\n  isMain    Boolean @default(false)\n  imageType String?\n  buyCar    BuyCar  @relation(fields: [carId], references: [id], onDelete: Cascade)\n\n  @@index([carId])\n}\n\nmodel RentalCar {\n  id         String  @id @default(cuid())\n  make       String\n  model      String\n  trim       String?\n  year       Int\n  hourlyRate Float\n  dailyRate  Float\n  weeklyRate Float\n\n  // Enhanced specifications from Supercar Pricing Aggregator\n  specifications Json // Enhanced with SPA performance data\n  features       Json // Interior, exterior, safety features\n\n  // Supercar Pricing Aggregator specific fields\n  supercarData    Json? // Full SPA comprehensive data\n  baseMSRP        Float? // Base MSRP from SPA for reference\n  performanceData Json? // Engine, horsepower, torque, 0-60, top speed, etc.\n\n  description     String           @db.Text\n  isAvailable     Boolean          @default(true)\n  stripeProductId String?\n  createdAt       DateTime         @default(now())\n  updatedAt       DateTime         @updatedAt\n  images          RentalCarImage[]\n  rentals         Rental[]\n}\n\nmodel RentalCarImage {\n  id        String    @id @default(cuid())\n  url       String\n  carId     String\n  isMain    Boolean   @default(false)\n  imageType String?\n  rentalCar RentalCar @relation(fields: [carId], references: [id], onDelete: Cascade)\n\n  @@index([carId])\n}\n\nmodel Quote {\n  id              String          @id @default(cuid())\n  userId          String\n  carId           String\n  amount          Float\n  financingOption Boolean         @default(false)\n  financingTerm   Int?\n  monthlyPayment  Float?\n  cashDeposit     Float?\n  tradeInIncluded Boolean         @default(false)\n  quoteStatus     QuoteStatus     @default(PENDING)\n  createdAt       DateTime        @default(now())\n  updatedAt       DateTime        @updatedAt\n  car             BuyCar          @relation(fields: [carId], references: [id])\n  user            User            @relation(fields: [userId], references: [id])\n  tradeInRequest  TradeInRequest?\n\n  @@index([carId])\n  @@index([userId])\n}\n\nmodel Rental {\n  id                    String         @id @default(cuid())\n  userId                String\n  carId                 String\n  startDate             DateTime\n  endDate               DateTime\n  rentalDuration        RentalDuration\n  totalAmount           Float\n  paymentStatus         PaymentStatus  @default(PENDING)\n  rentalStatus          RentalStatus   @default(RESERVED)\n  isSplitPayment        Boolean        @default(false)\n  stripePaymentIntentId String?\n  stripeSessionId       String?\n  paymentMethod         String?\n  depositAmount         Float?\n  depositRefunded       Boolean?\n  createdAt             DateTime       @default(now())\n  updatedAt             DateTime       @updatedAt\n  coRenters             CoRenter[]\n  car                   RentalCar      @relation(fields: [carId], references: [id])\n  user                  User           @relation(fields: [userId], references: [id])\n\n  @@index([carId])\n  @@index([userId])\n}\n\nmodel CoRenter {\n  id                    String        @id @default(cuid())\n  rentalId              String\n  email                 String\n  name                  String?\n  paymentAmount         Float\n  paymentStatus         PaymentStatus @default(PENDING)\n  stripePaymentIntentId String?\n  stripeSessionId       String?\n  paymentMethod         String?\n  invitationSent        Boolean       @default(false)\n  invitationAccepted    Boolean       @default(false)\n  createdAt             DateTime      @default(now())\n  updatedAt             DateTime      @updatedAt\n  rental                Rental        @relation(fields: [rentalId], references: [id], onDelete: Cascade)\n\n  @@index([rentalId])\n}\n\nmodel TradeInRequest {\n  id                       String        @id @default(cuid())\n  quoteId                  String        @unique\n  userId                   String\n  registrationNumber       String\n  make                     String?\n  model                    String\n  colour                   String?\n  fuelType                 String?\n  engineCapacity           Int?\n  yearOfManufacture        Int?\n  monthOfFirstRegistration String?\n  motStatus                String?\n  taxStatus                String?\n  taxDueDate               DateTime?\n  co2Emissions             Int?\n  euroStatus               String?\n  mileage                  Int\n  condition                String\n  conditionDetails         String?\n  accidentHistory          Boolean\n  numberOfAccidents        Int?\n  previousOwners           Int\n  fullServiceHistory       Boolean?\n  hasModifications         Boolean?\n  interiorCondition        Int?\n  exteriorCondition        Int?\n  images                   Json?\n  estimatedValue           Float?\n  actualValue              Float?\n  status                   TradeInStatus @default(PENDING)\n  adminNotes               String?\n  createdAt                DateTime      @default(now())\n  updatedAt                DateTime      @updatedAt\n  quote                    Quote         @relation(fields: [quoteId], references: [id])\n  user                     User          @relation(fields: [userId], references: [id])\n\n  @@index([userId])\n  @@index([registrationNumber])\n}\n\nmodel StripeProduct {\n  id            String   @id\n  name          String\n  description   String?\n  active        Boolean  @default(true)\n  type          String\n  defaultAmount Float?\n  currency      String   @default(\"GBP\")\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n}\n\nenum Role {\n  USER\n  ADMIN\n}\n\nenum PaymentStatus {\n  PENDING\n  PAID\n  FAILED\n  REFUNDED\n}\n\nenum QuoteStatus {\n  PENDING\n  GENERATED\n  RESERVED\n  CANCELLED\n}\n\nenum RentalStatus {\n  RESERVED\n  PAID\n  PICKED_UP\n  ACTIVE\n  RETURNED\n  COMPLETED\n  CANCELLED\n}\n\nenum RentalDuration {\n  HOURLY\n  DAILY\n  WEEKLY\n}\n\nenum TradeInStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  COMPLETED\n}\n",
